// Generated by Suite Builder from a crawl of the site. Calls the site's API and checks the answers:
// Api.site().get("/api/...").expectStatus(200).
// EDIT RULES: do not edit this file; regenerating replaces all of it. Your own API helpers go in a class of your own
// beside it.
package com.spiralmm.tests.core;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Calls the site's API and checks the answers, as a test does: no browser, Java's own HTTP client.
 * <pre>
 * Api.site().get("/api/products").expectStatus(200).expectJson("items[0].name", "Lamp");
 * Api.site().asRole("user").post("/api/cart", "{\"id\": 3}").expectStatus(201);
 * </pre>
 * The address is the site under test's (-DbaseUrl as the page tests), or Api.at(...) for another.
 * An account comes from secrets/ (asRole), a token from -D or the environment (bearer, with
 * SiteConfig.secret): never a literal in the code. Each call is a step in the test's log, so a
 * failure's evidence says what was asked and what came back.
 */
public final class Api {
    // HTTP/1.1, which every API answers: the default (HTTP/2) first asks a plain-http server to upgrade. A redirect is
    // an answer, not followed: a login page or another site answering for the API is no answer of its own.
    private static final HttpClient CLIENT = HttpClient.newBuilder()
            .version(HttpClient.Version.HTTP_1_1)
            .followRedirects(HttpClient.Redirect.NEVER)
            .connectTimeout(Duration.ofSeconds(15))
            .build();
    private static final HttpClient FOLLOWING = HttpClient.newBuilder()
            .version(HttpClient.Version.HTTP_1_1)
            .followRedirects(HttpClient.Redirect.NORMAL)
            .connectTimeout(Duration.ofSeconds(15))
            .build();
    private static final Duration TIMEOUT = Duration.ofSeconds(30);
    /** The least time between two calls, every test's: a site's rate limit never asked to stop the run. */
    private static final long PACE_MS = 200;
    /** The User-Agent the crawl used, as the browser tests send it: -DuserAgent, else the crawl's ("": Java's own). */
    private static final String CRAWL_USER_AGENT =
            "Mozilla/5.0 (compatible; SuiteBuilder/1.0; "
            + "+https://github.com/Ghost-in-the-Kernel-Labs/Ghost-in-the-Kernel-Labs-suite-builder-docs)";
    private static long lastCall;
    /** An answer of any success (2xx): Api.answer(Api.ANY_SUCCESS). */
    public static final int ANY_SUCCESS = -1;

    private final String base;
    private final Map<String, String> headers = new LinkedHashMap<>();
    private boolean follow;

    private Api(String base) {
        this.base = base.replaceAll("/+$", "");
        // JSON first, anything else said as it comes: an operation that answers text is not refused (406) for asking.
        headers.put("Accept", "application/json, */*;q=0.5");
        String agent = System.getProperty("userAgent", CRAWL_USER_AGENT);
        if (!agent.isBlank()) headers.put("User-Agent", agent);
    }

    /** Follows redirects, for a call that means to: an API answer's redirect is otherwise the answer. */
    public Api followRedirects() {
        follow = true;
        return this;
    }

    /**
     * An answer its document lists, for expectOneOf: its status (ANY_SUCCESS, any 2xx) and the media types it may come
     * as (none: any).
     */
    public static Answer answer(int status, String... media) {
        return new Answer(status, media);
    }

    /** The site under test: the baseUrl setting, else the address the crawl read. */
    public static Api site() {
        return new Api(SiteConfig.baseUrl());
    }

    /** Another address: a separate API host, say. */
    public static Api at(String baseUrl) {
        return new Api(baseUrl);
    }

    /** A header on every call made with this client. */
    public Api header(String name, String value) {
        headers.put(name, value);
        return this;
    }

    /** A bearer token: pass it from a secret, Api.site().bearer(SiteConfig.secret("apiToken")). */
    public Api bearer(String token) {
        return header("Authorization", "Bearer " + token);
    }

    /** Basic authentication as a role's account (secrets/&lt;role&gt;.login, or its environment variables). */
    public Api asRole(String role) {
        Credentials.Account account = Credentials.of(role);
        String pair = account.username() + ":" + account.password();
        return header("Authorization", "Basic " + Base64.getEncoder()
                .encodeToString(pair.getBytes(StandardCharsets.UTF_8)));
    }

    public Response get(String path) {
        return send("GET", path, null);
    }

    public Response delete(String path) {
        return send("DELETE", path, null);
    }

    public Response post(String path, String json) {
        return send("POST", path, json);
    }

    public Response put(String path, String json) {
        return send("PUT", path, json);
    }

    public Response patch(String path, String json) {
        return send("PATCH", path, json);
    }

    private Response send(String method, String path, String json) {
        String url = path.matches("^https?://.*") ? path : base + (path.startsWith("/") ? path : "/" + path);
        HttpRequest.Builder request = HttpRequest.newBuilder(URI.create(url)).timeout(TIMEOUT)
                .method(method,
                        json == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(json));
        headers.forEach(request::header);
        if (json != null) request.header("Content-Type", "application/json");
        StepLog.step(method + " " + url);
        pace();
        long started = System.nanoTime();
        try {
            HttpResponse<String> answer = (follow ? FOLLOWING : CLIENT)
                    .send(request.build(), HttpResponse.BodyHandlers.ofString());
            long ms = (System.nanoTime() - started) / 1_000_000;
            StepLog.note(method + " " + url + " answered " + answer.statusCode() + " in " + ms + " ms");
            // Its row in the run's API timings, by its path (the same call against another -DbaseUrl compares).
            URI asked = URI.create(url);
            String over = Timings.recordApi(method + " " + asked.getRawPath()
                    + (asked.getRawQuery() == null ? "" : "?" + asked.getRawQuery()), answer.statusCode(), ms);
            lastCall = System.nanoTime();
            if (over != null) throw new AssertionError(over);
            return new Response(method + " " + url, answer.statusCode(), answer.body(), answer.headers().map(), ms);
        } catch (IOException e) {
            throw new AssertionError(method + " " + url + " got no answer: " + e.getMessage(), e);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new AssertionError(method + " " + url + " was interrupted", e);
        }
    }

    /** Waits, when the last call was under PACE_MS ago. */
    private static synchronized void pace() {
        long since = (System.nanoTime() - lastCall) / 1_000_000;
        if (lastCall == 0 || since >= PACE_MS) return;
        try {
            Thread.sleep(PACE_MS - since);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    /**
     * One answer an API document lists as a success, for {@link Response#expectOneOf}: its status, the media types it
     * may come as, and its JSON: any JSON (json()), or an object or an array (each item) with each field given as
     * "name:type" (string, number, integer, boolean, object, array or any) and "|null" when it may be null.
     */
    public static final class Answer {
        final int status;
        final List<String> media;
        private String json;
        private final List<String> fields = new ArrayList<>();

        Answer(int status, String... media) {
            this.status = status;
            this.media = List.of(media);
        }

        /** Its body is JSON, of any shape. */
        public Answer json() {
            json = "any";
            return this;
        }

        /** Its body is a JSON object with each field given ("name:type", "|null" when it may be null). */
        public Answer object(String... fields) {
            json = "object";
            this.fields.addAll(List.of(fields));
            return this;
        }

        /** Its body is a JSON array; each item an object with each field given. */
        public Answer array(String... fields) {
            json = "array";
            this.fields.addAll(List.of(fields));
            return this;
        }

        boolean statusIs(int s) {
            return status == ANY_SUCCESS ? s >= 200 && s <= 299 : s == status;
        }

        String said() {
            return status == ANY_SUCCESS ? "a success (2xx)" : String.valueOf(status);
        }

        /** Why the answer is not this one, or null when it is. */
        String mismatch(Response r) {
            if (!media.isEmpty() && !media.contains("*/*")) {
                String type = r.header("Content-Type");
                String base = type == null ? "" : type.split(";")[0].trim().toLowerCase(java.util.Locale.ROOT);
                boolean listed = false;
                for (String m : media) listed |= m.equals(base)
                        || (m.endsWith("/*") && base.startsWith(m.substring(0, m.length() - 1)));
                if (!listed) return "answered " + (base.isEmpty() ? "with no Content-Type" : base)
                        + ", where its document lists " + String.join(", ", media);
            }
            if (json == null) return null;
            Object body;
            try {
                body = r.json();
            } catch (AssertionError e) {
                // Json.read says what was asked first: said once, by fail().
                String why = String.valueOf(e.getMessage());
                int at = why.indexOf("did not answer JSON: ");
                return "did not answer JSON (" + (at < 0 ? why : why.substring(at + 21)) + ")";
            }
            if (json.equals("object")) return body instanceof Map<?,
                    ?> map ? fieldsMissing(map, "") : "is no JSON object";
            if (json.equals("array")) {
                if (!(body instanceof List<?> list)) return "is no JSON array";
                if (list.isEmpty() && !fields.isEmpty()) StepLog.note("an empty array: no item to check its fields");
                for (int i = 0; i < list.size() && !fields.isEmpty(); i++) {
                    if (!(list.get(i) instanceof Map<?, ?> item)) return "has item " + i + ", no JSON object";
                    String why = fieldsMissing(item, "item " + i + " with ");
                    if (why != null) return why;
                }
            }
            return null;
        }

        private String fieldsMissing(Map<?, ?> object, String where) {
            for (String spec : fields) {
                int colon = spec.lastIndexOf(':');
                String name = colon < 0 ? spec : spec.substring(0, colon);
                String type = colon < 0 ? "any" : spec.substring(colon + 1);
                boolean nullable = type.endsWith("|null");
                if (nullable) type = type.substring(0, type.length() - 5);
                if (!object.containsKey(name)) return "has " + where + "no field \"" + name + "\"";
                Object value = object.get(name);
                if (value == null) {
                    if (!nullable) return "has " + where + "field \"" + name
                            + "\" null, where its document says it is not";
                    continue;
                }
                boolean is = switch (type) {
                    case "string" -> value instanceof String;
                    case "number" -> value instanceof Double;
                    case "integer" -> value instanceof Double d && d == Math.rint(d) && !d.isInfinite();
                    case "boolean" -> value instanceof Boolean;
                    case "object" -> value instanceof Map;
                    case "array" -> value instanceof List;
                    default -> true;
                };
                if (!is) return "has " + where + "field \"" + name + "\" = " + value
                        + ", where its document says its type is " + type;
            }
            return null;
        }
    }

    /** An answer, and the checks on it; each check fails saying what was asked and what came back. */
    public static final class Response {
        private final String asked;
        private final int status;
        private final String body;
        private final Map<String, List<String>> headers;
        private final long ms;
        private Object json;

        Response(String asked, int status, String body, Map<String, List<String>> headers, long ms) {
            this.asked = asked;
            this.status = status;
            this.body = body;
            this.headers = headers;
            this.ms = ms;
        }

        public int status() {
            return status;
        }

        public String body() {
            return body;
        }

        public long ms() {
            return ms;
        }

        /** A header's first value, or null. */
        public String header(String name) {
            for (Map.Entry<String, List<String>> e : headers.entrySet()) {
                if (e.getKey().equalsIgnoreCase(name) && !e.getValue().isEmpty()) return e.getValue().get(0);
            }
            return null;
        }

        /** The answer's JSON, read: a Map, a List, a String, a Double, a Boolean or null. */
        public Object json() {
            if (json == null) json = Json.read(body, asked);
            return json;
        }

        /** A value in the answer's JSON by its path: "items[0].name", "total", "[2].id". */
        public Object value(String path) {
            Object at = json();
            for (String part : path.replace("[", ".[").split("\\.")) {
                if (part.isEmpty()) continue;
                if (part.startsWith("[")) {
                    int i = Integer.parseInt(part.substring(1, part.length() - 1));
                    if (!(at instanceof List<?> list) || i >= list.size()) throw fail("has no " + path + " (no item "
                            + i + ")");
                    at = list.get(i);
                } else {
                    if (!(at instanceof Map<?, ?> map) || !map.containsKey(part)) throw fail("has no " + path
                            + " (no field \"" + part + "\")");
                    at = map.get(part);
                }
            }
            return at;
        }

        public Response expectStatus(int expected) {
            if (status != expected) throw fail("answered " + status + ", where " + expected + " was expected");
            return this;
        }

        /** The answer is a success: one of the statuses given, or, given none, any 2xx. */
        public Response expectSuccess(int... statuses) {
            boolean listed = false;
            for (int s : statuses) listed |= s == status;
            if (statuses.length == 0 ? status < 200 || status > 299 : !listed) {
                throw fail("answered " + status + ", where "
                        + (statuses.length == 0 ? "a success (2xx)" : "one of " + Arrays.toString(statuses))
                        + " was expected");
            }
            return this;
        }

        /** The answer's JSON is an object with each field given. */
        public Response expectObject(String... fields) {
            if (!(json() instanceof Map<?, ?> map)) throw fail("is no JSON object");
            for (String field : fields) {
                if (!map.containsKey(field)) throw fail("has no field \"" + field + "\"");
            }
            return this;
        }

        /** The answer's JSON is an array; given fields, each item is an object with each of them. */
        public Response expectArray(String... fields) {
            if (!(json() instanceof List<?> list)) throw fail("is no JSON array");
            for (int i = 0; fields.length > 0 && i < list.size(); i++) {
                if (!(list.get(i) instanceof Map<?, ?> item)) throw fail("has item " + i + ", no JSON object");
                for (String field : fields) {
                    if (!item.containsKey(field)) throw fail("has item " + i + " with no field \"" + field + "\"");
                }
            }
            return this;
        }

        /**
         * The answer is one its document lists (the generated API tests): its status, then its media type and JSON as
         * that
         * answer says. A 3xx not listed fails naming where it points. 429, or 503 with Retry-After, not listed: the
         * site
         * asked the suite to wait, and the test is skipped, saying so, not judged.
         */
        public Response expectOneOf(Answer... answers) {
            boolean listed = false;
            for (Answer a : answers) listed |= a.statusIs(status);
            if (!listed && (status == 429 || (status == 503 && header("Retry-After") != null))) {
                String wait = header("Retry-After");
                throw new Checks.NotMet(asked + " answered " + status
                        + (wait == null ? "" : " (Retry-After: " + wait + ")")
                        + ": the site asked the suite to wait; not judged");
            }
            List<String> said = new ArrayList<>();
            for (Answer a : answers) said.add(a.said());
            if (!listed) {
                String to = status >= 300 && status <= 399 && header("Location") != null ? " (to " + header("Location")
                        + ")" : "";
                throw fail("answered " + status + to + ", where its document lists " + String.join(", ", said));
            }
            String why = null;
            for (Answer a : answers) {
                if (!a.statusIs(status)) continue;
                why = a.mismatch(this);
                if (why == null) return this;
            }
            throw fail(why);
        }

        /** The answer has the path, whatever its value. */
        public Response expectJson(String path) {
            value(path);
            return this;
        }

        /** The value at the path equals the one given (a number compared as a number). */
        public Response expectJson(String path, Object expected) {
            Object actual = value(path);
            boolean same = actual instanceof Number a
                    && expected instanceof Number e ? a.doubleValue() == e.doubleValue() : String.valueOf(actual)
                    .equals(String.valueOf(expected));
            if (!same) throw fail("has " + path + " = " + actual + ", where " + expected + " was expected");
            return this;
        }

        /** The answer came within the given milliseconds. */
        public Response expectFasterThan(long millis) {
            if (ms > millis) throw fail("took " + ms + " ms, over " + millis + " ms");
            return this;
        }

        private AssertionError fail(String what) {
            String shown = body.length() > 500 ? body.substring(0, 500) + "..." : body;
            return new AssertionError(asked + " " + what + ". The answer (" + status + "): " + shown);
        }
    }

    /** A small JSON reader (no library): objects to Maps, arrays to Lists, numbers to Doubles. */
    private static final class Json {
        private final String text;
        private final String asked;
        private int at;

        private Json(String text, String asked) {
            this.text = text;
            this.asked = asked;
        }

        static Object read(String text, String asked) {
            // A byte-order mark before the JSON is no part of it (Node's and the browser's readers drop it too).
            String body = text == null ? "" : text.startsWith("\uFEFF") ? text.substring(1) : text;
            Json json = new Json(body, asked);
            Object value = json.value();
            json.space();
            if (json.at != json.text.length()) throw json.wrong("more after the end");
            return value;
        }

        private Object value() {
            space();
            if (at >= text.length()) throw wrong("nothing");
            char c = text.charAt(at);
            if (c == '{') return object();
            if (c == '[') return array();
            if (c == '"') return string();
            if (text.startsWith("true", at)) { at += 4; return Boolean.TRUE; }
            if (text.startsWith("false", at)) { at += 5; return Boolean.FALSE; }
            if (text.startsWith("null", at)) { at += 4; return null; }
            int start = at;
            while (at < text.length() && "+-0123456789.eE".indexOf(text.charAt(at)) >= 0) at++;
            if (start == at) throw wrong("'" + c + "'");
            return Double.parseDouble(text.substring(start, at));
        }

        private Map<String, Object> object() {
            Map<String, Object> map = new LinkedHashMap<>();
            at++;
            space();
            if (peek() == '}') { at++; return map; }
            while (true) {
                space();
                String key = string();
                space();
                expect(':');
                map.put(key, value());
                space();
                if (peek() == ',') { at++; continue; }
                expect('}');
                return map;
            }
        }

        private List<Object> array() {
            List<Object> list = new ArrayList<>();
            at++;
            space();
            if (peek() == ']') { at++; return list; }
            while (true) {
                list.add(value());
                space();
                if (peek() == ',') { at++; continue; }
                expect(']');
                return list;
            }
        }

        private String string() {
            expect('"');
            StringBuilder out = new StringBuilder();
            while (at < text.length() && text.charAt(at) != '"') {
                char c = text.charAt(at++);
                if (c != '\\') { out.append(c); continue; }
                char e = text.charAt(at++);
                switch (e) {
                    case 'n' -> out.append('\n');
                    case 't' -> out.append('\t');
                    case 'r' -> out.append('\r');
                    case 'b' -> out.append('\b');
                    case 'f' -> out.append('\f');
                    case 'u' -> { out.append((char) Integer.parseInt(text.substring(at, at + 4), 16)); at += 4; }
                    default -> out.append(e);
                }
            }
            expect('"');
            return out.toString();
        }

        private char peek() {
            return at < text.length() ? text.charAt(at) : '\0';
        }

        private void expect(char c) {
            if (peek() != c) throw wrong("'" + peek() + "' where '" + c + "' belongs");
            at++;
        }

        private void space() {
            while (at < text.length() && Character.isWhitespace(text.charAt(at))) at++;
        }

        private AssertionError wrong(String what) {
            return new AssertionError(asked + " did not answer JSON: " + what + " at character " + at);
        }
    }
}
